{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    required = ("nodes", "core_distance", "distances")
    if any(key not in case for key in required):
        raise ValueError("missing required field")

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or any(not isinstance(node, str) for node in nodes):
        raise ValueError("nodes must be a list of strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("nodes must be unique")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be an object")
    if set(core_distance) != set(nodes):
        raise ValueError("core_distance keys must match nodes")
    for node in nodes:
        value = core_distance[node]
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
            raise ValueError("invalid core distance")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    node_set = set(nodes)
    edges = []
    seen = set()
    for item in distances:
        if not isinstance(item, list) or len(item) != 3:
            raise ValueError("each distance must be a triple")
        left, right, distance = item
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("edge endpoints must be strings")
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("invalid edge endpoint")
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or not math.isfinite(distance):
            raise ValueError("invalid distance")
        endpoints = tuple(sorted((left, right)))
        if endpoints in seen:
            raise ValueError("duplicate undirected edge")
        seen.add(endpoints)
        weight = max(core_distance[left], core_distance[right], distance)
        edges.append((weight, endpoints[0], endpoints[1]))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right]:
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, left, right in edges:
        if union(left, right):
            mst_edges.append([left, right, weight])
            total_weight += weight
            if len(mst_edges) == max(0, len(nodes) - 1):
                break

    if len(mst_edges) != max(0, len(nodes) - 1):
        raise ValueError("disconnected graph")
    return {"mst_edges": mst_edges, "total_weight": total_weight}
